def minimum_xor_assignment_sum(nums1, nums2):
    size = 1 << len(nums2)
    infinity = float("inf")
    best = [infinity] * size
    best[0] = 0
    for mask in range(size):
        index = mask.bit_count()
        if index == len(nums1):
            continue
        for candidate, value in enumerate(nums2):
            bit = 1 << candidate
            if mask & bit == 0:
                next_mask = mask | bit
                best[next_mask] = min(best[next_mask], best[mask] + (nums1[index] ^ value))
    return best[-1]

